const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// -----------------------------------------------------\n// Module: admin.prisma\n// -----------------------------------------------------\nmodel AdminAuditLog {\n  id         String   @id @default(uuid())\n  actorId    String\n  actorRole  String\n  action     String\n  targetType String\n  targetId   String?\n  details    Json?\n  ipAddress  String?\n  userAgent  String?\n  createdAt  DateTime @default(now())\n\n  @@map(\"admin_audit_logs\")\n}\n\nmodel NotificationItem {\n  id          String    @id\n  candidateId String\n  candidate   Candidate @relation(fields: [candidateId], references: [id], onDelete: Cascade)\n  title       String\n  message     String\n  type        String    @default(\"info\")\n  isRead      Boolean   @default(false)\n  actionUrl   String?\n  createdAt   DateTime  @default(now())\n\n  @@map(\"notifications\")\n}\n\nmodel UserJobReminder {\n  id              String      @id @default(uuid())\n  candidateId     String\n  candidate       Candidate   @relation(fields: [candidateId], references: [id], onDelete: Cascade)\n  jobId           String\n  job             JobCircular @relation(fields: [jobId], references: [id], onDelete: Cascade)\n  alertDaysBefore Int         @default(1)\n  createdAt       DateTime    @default(now())\n\n  @@map(\"user_job_reminders\")\n}\n\nmodel DeadlineAlertRule {\n  id        String   @id @default(uuid())\n  name      String\n  condition String\n  channels  Json\n  isEnabled Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  @@map(\"deadline_alert_rules\")\n}\n\nmodel JobReport {\n  id             String   @id @default(uuid())\n  jobId          String\n  jobTitle       String?\n  candidateEmail String?\n  reporterName   String?\n  reporterPhone  String?\n  reason         String\n  details        String?\n  status         String   @default(\"pending\")\n  resolutionNote String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @default(now()) @updatedAt\n\n  @@map(\"job_reports\")\n}\n\nmodel JobAlertSubscription {\n  id         String   @id @default(uuid())\n  email      String\n  categories Json?\n  frequency  String   @default(\"daily\")\n  createdAt  DateTime @default(now())\n\n  @@map(\"job_alert_subscriptions\")\n}\n\nmodel ContactMessage {\n  id         String   @id @default(uuid())\n  ticketId   String?\n  name       String\n  email      String\n  phone      String?\n  subject    String\n  category   String?  @default(\"general\")\n  message    String\n  status     String   @default(\"unread\")\n  replyNotes String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @default(now()) @updatedAt\n\n  @@map(\"contact_messages\")\n}\n\nmodel ExpenseRecord {\n  id         String   @id @default(uuid())\n  title      String\n  category   String   @default(\"operations\")\n  amount     Decimal  @db.Decimal(12, 2)\n  notes      String?\n  incurredAt DateTime @default(now())\n  createdBy  String?\n  createdAt  DateTime @default(now())\n\n  @@map(\"expense_records\")\n}\n\nmodel OperationBudget {\n  id            String   @id @default(\"global\")\n  monthlyBudget Decimal  @default(100000) @db.Decimal(12, 2)\n  marketingCap  Decimal  @default(25000) @db.Decimal(12, 2)\n  infraCap      Decimal  @default(30000) @db.Decimal(12, 2)\n  updatedBy     String?\n  updatedAt     DateTime @updatedAt\n\n  @@map(\"operation_budgets\")\n}\n\nmodel PublishingQueueItem {\n  id          String    @id @default(uuid())\n  jobId       String?\n  title       String\n  channel     String    @default(\"website\")\n  status      String    @default(\"scheduled\")\n  payload     Json?\n  scheduledAt DateTime?\n  publishedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@map(\"publishing_queue_items\")\n}\n\nmodel RedirectRule {\n  id         String   @id @default(uuid())\n  fromPath   String   @unique\n  toPath     String\n  statusCode Int      @default(301)\n  isEnabled  Boolean  @default(true)\n  hitCount   Int      @default(0)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@map(\"redirect_rules\")\n}\n\nmodel FeaturedPlacement {\n  id        String    @id @default(uuid())\n  jobId     String\n  slot      String    @default(\"hero\")\n  priority  Int       @default(0)\n  isActive  Boolean   @default(true)\n  startsAt  DateTime?\n  endsAt    DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@map(\"featured_placements\")\n}\n\nmodel JobFeedConfig {\n  id         String   @id @default(uuid())\n  name       String\n  slug       String   @unique\n  feedType   String   @default(\"curated\")\n  rules      Json?\n  jobIds     Json?\n  isActive   Boolean  @default(true)\n  orderIndex Int      @default(0)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@map(\"job_feed_configs\")\n}\n\nmodel MatchingConfig {\n  id               String    @id @default(\"global\")\n  educationWeight  Int       @default(40)\n  skillsWeight     Int       @default(30)\n  districtWeight   Int       @default(15)\n  ageWeight        Int       @default(15)\n  minScore         Int       @default(40)\n  enableAiFallback Boolean   @default(false)\n  lastRebuiltAt    DateTime?\n  updatedAt        DateTime  @updatedAt\n\n  @@map(\"matching_configs\")\n}\n\nmodel ContentStudioDraft {\n  id              String   @id @default(uuid())\n  jobId           String?\n  title           String\n  status          String   @default(\"draft\")\n  qualityScore    Int      @default(0)\n  content         Json?\n  validationNotes Json?\n  revisions       Json?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@map(\"content_studio_drafts\")\n}\n\nmodel CircularChangeProposal {\n  id         String   @id @default(uuid())\n  jobId      String\n  field      String\n  oldValue   Json?\n  newValue   Json?\n  reason     String?\n  status     String   @default(\"pending\")\n  reviewedBy String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@map(\"circular_change_proposals\")\n}\n\nmodel NotificationDelivery {\n  id        String   @id @default(uuid())\n  channel   String   @default(\"in_app\")\n  recipient String\n  title     String\n  message   String\n  status    String   @default(\"sent\")\n  jobId     String?\n  metadata  Json?\n  createdAt DateTime @default(now())\n\n  @@map(\"notification_deliveries\")\n}\n\nmodel SpiderRunRecord {\n  id         String   @id @default(uuid())\n  sourceId   String?\n  sourceName String\n  status     String   @default(\"completed\")\n  itemsFound Int      @default(0)\n  itemsAdded Int      @default(0)\n  durationMs Int      @default(0)\n  error      String?\n  createdAt  DateTime @default(now())\n\n  @@map(\"spider_run_records\")\n}\n\nmodel SearchAnalyticsLog {\n  id          String   @id @default(uuid())\n  query       String\n  resultCount Int      @default(0)\n  category    String?\n  createdAt   DateTime @default(now())\n\n  @@map(\"search_analytics_logs\")\n}\n\n// -----------------------------------------------------\n// Module: application.prisma\n// -----------------------------------------------------\nmodel ApplicationRequest {\n  id                   String            @id\n  candidateId          String\n  candidate            Candidate         @relation(fields: [candidateId], references: [id], onDelete: Cascade)\n  jobId                String\n  job                  JobCircular       @relation(fields: [jobId], references: [id], onDelete: Cascade)\n  positionIndex        Int               @default(0)\n  positionName         String\n  trackingNumber       String            @unique\n  status               ApplicationStatus @default(PENDING)\n  govtFee              Decimal           @db.Decimal(10, 2)\n  serviceFee           Decimal           @db.Decimal(10, 2)\n  discount             Decimal           @default(0.00) @db.Decimal(10, 2)\n  totalPaid            Decimal           @db.Decimal(10, 2)\n  paymentMethod        String            @default(\"wallet\")\n  splitWalletAmount    Decimal?          @db.Decimal(10, 2)\n  transactionId        String?\n  paymentScreenshotUrl String?\n  submissionChannel    String?\n  applicantCopyPdfUrl  String?\n  admitCardUrl         String?\n  teletalkUserId       String?\n  teleTalkPassword     String?\n  corporateTrackingId  String?\n  rollNumber           String?\n  operatorNotes        String?\n  statusHistory        Json? // Array of status changes [{status, timestamp, note}]\n  submittedAt          DateTime          @default(now())\n  updatedAt            DateTime          @updatedAt\n\n  @@map(\"application_requests\")\n}\n\nmodel CompanyProfile {\n  id          String   @id\n  companyName String\n  slug        String?\n  type        String?  @default(\"private\")\n  websiteUrl  String?\n  logoUrl     String?\n  isVerified  Boolean  @default(false)\n  email       String?\n  phone       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"company_profiles\")\n}\n\nmodel CompanyApplication {\n  id          String   @id @default(uuid())\n  companyId   String\n  candidateId String\n  jobId       String\n  status      String   @default(\"pending\")\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"company_applications\")\n}\n\n// -----------------------------------------------------\n// Module: auth.prisma\n// -----------------------------------------------------\nmodel Candidate {\n  id              String     @id @default(uuid())\n  email           String     @unique\n  phone           String?    @unique\n  username        String     @unique\n  name            String\n  nameBn          String?\n  passwordHash    String\n  role            UserRole   @default(CANDIDATE)\n  status          UserStatus @default(ACTIVE)\n  isEmailVerified Boolean    @default(false)\n  isVerified      Boolean    @default(false)\n  adminNote       String?\n  walletBalance   Decimal    @default(0.00) @db.Decimal(12, 2)\n  district        String?\n  division        String?\n  avatarUrl       String?\n  googleId        String?\n  createdAt       DateTime   @default(now())\n  updatedAt       DateTime   @updatedAt\n\n  // Extended Smart Profile Fields (Govt / Teletalk / Bank Standard)\n  fatherName              String?\n  fatherNameBn            String?\n  motherName              String?\n  motherNameBn            String?\n  fatherNid               String?\n  motherNid               String?\n  dob                     String?\n  gender                  String?  @default(\"male\")\n  nid                     String?\n  address                 String?\n  permanentAddress        String?\n  sameAsPresentAddress    Boolean? @default(true)\n  maritalStatus           String?  @default(\"single\")\n  religion                String?\n  nationality             String?  @default(\"বাংলাদেশি (Bangladeshi)\")\n  photoUrl                String?\n  signatureUrl            String?\n  nidFrontUrl             String?\n  nidBackUrl              String?\n  fatherNidUrl            String?\n  motherNidUrl            String?\n  nagorikCertificateUrl   String?\n  birthCertificateUrl     String?\n  characterCertificateUrl String?\n  quota                   String?  @default(\"none\")\n  quotaCertificateUrl     String?\n  skills                  Json?    @default(\"[]\")\n  experiences             Json?    @default(\"[]\")\n  presentAddressDetails   Json?\n  permanentAddressDetails Json?\n  careerObjective         String?\n  professionalSummary     String?\n  currentPosition         String?\n  currentOrganization     String?\n  careerPreferences       Json?\n\n  sessions          Session[]\n  documents         CandidateDocument[]\n  educations        EducationRecord[]\n  applications      ApplicationRequest[]\n  transactions      WalletTransaction[]\n  savedJobs         SavedJob[]\n  notifications     NotificationItem[]\n  jobReminders      UserJobReminder[]\n  couponRedemptions CouponRedemption[]\n  raffleEntries     RaffleEntry[]\n\n  @@map(\"candidates\")\n}\n\nmodel Session {\n  id           String    @id @default(uuid())\n  candidateId  String\n  candidate    Candidate @relation(fields: [candidateId], references: [id], onDelete: Cascade)\n  refreshToken String    @unique\n  ipAddress    String?\n  userAgent    String?\n  expiresAt    DateTime\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@map(\"sessions\")\n}\n\nmodel VerificationOtp {\n  id          String   @id @default(uuid())\n  email       String\n  otp         String\n  type        OtpType  @default(VERIFY_EMAIL)\n  candidateId String?\n  expiresAt   DateTime\n  isUsed      Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"verification_otps\")\n}\n\nmodel StaffMember {\n  id          String   @id @default(uuid())\n  name        String\n  email       String   @unique\n  role        UserRole @default(OPERATOR)\n  permissions Json?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"staff_members\")\n}\n\n// -----------------------------------------------------\n// Module: candidate.prisma\n// -----------------------------------------------------\nmodel EducationRecord {\n  id                  String    @id @default(uuid())\n  candidateId         String\n  candidate           Candidate @relation(fields: [candidateId], references: [id], onDelete: Cascade)\n  level               String\n  examTitle           String\n  groupMajor          String?\n  boardUniversity     String?\n  institute           String?\n  rollNumber          String?\n  regNumber           String?\n  passingYear         Int\n  resultType          String?\n  gpaCgpa             Float?\n  scale               Float?\n  verificationStatus  String    @default(\"pending\")\n  verificationRemarks String?\n  createdAt           DateTime  @default(now())\n  updatedAt           DateTime  @updatedAt\n\n  @@map(\"education_records\")\n}\n\nmodel CandidateDocument {\n  id                  String       @id @default(uuid())\n  candidateId         String\n  candidate           Candidate    @relation(fields: [candidateId], references: [id], onDelete: Cascade)\n  type                DocumentType\n  slotType            String?\n  category            String?\n  title               String\n  fileUrl             String\n  fileSize            Int?\n  mimeType            String?\n  isVerified          Boolean      @default(false)\n  verificationStatus  String       @default(\"pending\")\n  verificationRemarks String?\n  createdAt           DateTime     @default(now())\n  updatedAt           DateTime     @updatedAt\n\n  @@map(\"candidate_documents\")\n}\n\nmodel SavedJob {\n  id          String      @id @default(uuid())\n  candidateId String\n  candidate   Candidate   @relation(fields: [candidateId], references: [id], onDelete: Cascade)\n  jobId       String\n  job         JobCircular @relation(fields: [jobId], references: [id], onDelete: Cascade)\n  createdAt   DateTime    @default(now())\n\n  @@unique([candidateId, jobId])\n  @@map(\"saved_jobs\")\n}\n\n// -----------------------------------------------------\n// Module: cms.prisma\n// -----------------------------------------------------\nmodel PageRecord {\n  id              String    @id\n  slug            String    @unique\n  title           String\n  metaTitle       String?\n  metaDescription String?\n  status          String    @default(\"published\")\n  version         Int       @default(1)\n  isSystemPage    Boolean   @default(false)\n  sections        Json // Array of Page Builder Sections\n  revisions       Json?\n  publishedAt     DateTime?\n  updatedAt       DateTime  @updatedAt\n\n  @@map(\"pages\")\n}\n\nmodel MediaItem {\n  id           String   @id @default(uuid())\n  filename     String\n  originalName String?\n  fileUrl      String\n  fileSize     Int?\n  mimeType     String?\n  altText      String?\n  caption      String?\n  category     String?  @default(\"general\")\n  dimensions   Json?\n  createdAt    DateTime @default(now())\n\n  @@map(\"media_items\")\n}\n\nmodel PlatformSettings {\n  id           String   @id @default(\"global\")\n  siteName     String   @default(\"চাকরি সেবা\")\n  tagline      String?\n  contactEmail String?\n  supportPhone String?\n  headerMenu   Json?\n  footerMenu   Json?\n  seoDefaults  Json?\n  general      Json?\n  workflow     Json?\n  operational  Json?\n  updatedAt    DateTime @updatedAt\n\n  @@map(\"platform_settings\")\n}\n\nmodel BlogPost {\n  id          String   @id @default(uuid())\n  slug        String   @unique\n  kind        String   @default(\"blog\") // blog | guide\n  title       String\n  excerpt     String?\n  content     String\n  category    String?\n  author      String?\n  coverImage  String?\n  readTime    String?\n  tags        Json?\n  status      String   @default(\"published\")\n  publishedAt DateTime @default(now())\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([kind, status])\n  @@map(\"blog_posts\")\n}\n\nmodel CandidateReview {\n  id          String   @id @default(uuid())\n  name        String\n  role        String?\n  institution String?\n  quote       String\n  rating      Int      @default(5)\n  isApproved  Boolean  @default(true)\n  orderIndex  Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"candidate_reviews\")\n}\n\n// -----------------------------------------------------\n// Module: enums.prisma\n// -----------------------------------------------------\nenum UserRole {\n  CANDIDATE\n  ADMIN\n  OPERATOR\n  EDITOR\n}\n\nenum UserStatus {\n  ACTIVE\n  INACTIVE\n  SUSPENDED\n  DELETED\n}\n\nenum OtpType {\n  VERIFY_EMAIL\n  RESET_PASSWORD\n  LOGIN_OTP\n}\n\nenum ApplicationStatus {\n  PENDING\n  PROCESSING\n  PAYMENT_COMPLETED\n  COMPLETED\n  REJECTED\n  CANCELLED\n}\n\nenum TransactionType {\n  RECHARGE\n  APPLICATION_FEE\n  REFUND\n  CASHBACK\n  ADJUSTMENT\n}\n\nenum TransactionStatus {\n  PENDING\n  COMPLETED\n  FAILED\n  CANCELLED\n}\n\nenum JobStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n  EXPIRED\n}\n\nenum DiscountType {\n  PERCENTAGE\n  FIXED\n}\n\nenum CouponStatus {\n  ACTIVE\n  EXPIRED\n  DISABLED\n}\n\nenum ExamStage {\n  MCQ\n  WRITTEN\n  PRACTICAL\n  VIVA\n}\n\nenum DocumentType {\n  PHOTO_300x300\n  SIGNATURE_300x80\n  NID_CARD\n  BIRTH_CERTIFICATE\n  SSC_CERTIFICATE\n  HSC_CERTIFICATE\n  GRADUATION_CERTIFICATE\n  MASTERS_CERTIFICATE\n  QUOTA_CERTIFICATE\n  OTHER\n}\n\n// -----------------------------------------------------\n// Module: exam.prisma\n// -----------------------------------------------------\nmodel ExamNotice {\n  id           String       @id @default(uuid())\n  jobId        String?\n  job          JobCircular? @relation(fields: [jobId], references: [id], onDelete: SetNull)\n  title        String\n  organization String?\n  category     String?\n  stage        ExamStage    @default(WRITTEN)\n  examDate     DateTime?\n  examTime     String?\n  venue        String?\n  description  String?\n  noticeUrl    String?\n  status       String       @default(\"published\")\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  @@map(\"exam_notices\")\n}\n\nmodel AdmitCard {\n  id               String       @id @default(uuid())\n  jobId            String?\n  job              JobCircular? @relation(fields: [jobId], references: [id], onDelete: SetNull)\n  title            String\n  organization     String?\n  category         String?\n  examDate         DateTime?\n  deadline         DateTime?\n  downloadUrl      String?\n  rollInstructions String?\n  isAvailable      Boolean      @default(true)\n  status           String       @default(\"available\")\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n\n  @@map(\"admit_cards\")\n}\n\nmodel ExamResult {\n  id           String       @id @default(uuid())\n  jobId        String?\n  job          JobCircular? @relation(fields: [jobId], references: [id], onDelete: SetNull)\n  title        String\n  organization String?\n  category     String?\n  stage        ExamStage    @default(WRITTEN)\n  summary      String?\n  pdfUrl       String?\n  passedRolls  Json? // Array of passed roll numbers\n  publishedAt  DateTime     @default(now())\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  @@map(\"exam_results\")\n}\n\nmodel VivaNotice {\n  id           String    @id @default(uuid())\n  title        String\n  organization String?\n  category     String?\n  vivaDate     DateTime?\n  venue        String?\n  instructions String?\n  noticeUrl    String?\n  status       String    @default(\"published\")\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@map(\"viva_notices\")\n}\n\nmodel Question {\n  id           String   @id @default(uuid())\n  category     String // Bangla, English, Math, General Knowledge, etc.\n  question     String\n  options      Json // Array of choices [optionA, optionB, optionC, optionD]\n  correctIndex Int\n  explanation  String?\n  examYear     Int?\n  organization String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@map(\"questions\")\n}\n\nmodel ModelTest {\n  id              String             @id @default(uuid())\n  title           String\n  category        String\n  description     String?\n  totalMarks      Int                @default(100)\n  durationMinutes Int                @default(60)\n  negativeMark    Float              @default(0.25)\n  isPublished     Boolean            @default(true)\n  questions       Json // Array of questions / question IDs\n  createdAt       DateTime           @default(now())\n  updatedAt       DateTime           @updatedAt\n  attempts        ModelTestAttempt[]\n\n  @@map(\"model_tests\")\n}\n\nmodel ModelTestAttempt {\n  id             String    @id @default(uuid())\n  candidateId    String\n  modelTestId    String\n  modelTest      ModelTest @relation(fields: [modelTestId], references: [id], onDelete: Cascade)\n  category       String\n  totalQuestions Int\n  correctCount   Int\n  wrongCount     Int\n  skippedCount   Int       @default(0)\n  score          Float\n  totalMarks     Int\n  accuracy       Float\n  durationSec    Int?\n  answers        Json?\n  createdAt      DateTime  @default(now())\n\n  @@index([candidateId])\n  @@index([modelTestId])\n  @@map(\"model_test_attempts\")\n}\n\n// -----------------------------------------------------\n// Module: job.prisma\n// -----------------------------------------------------\nmodel JobCircular {\n  id               String    @id\n  slug             String    @unique\n  title            String\n  titleBn          String?\n  organization     String\n  organizationSlug String?\n  categoryId       String?\n  category         Category? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  deadline         DateTime\n  totalPositions   Int       @default(1)\n  officialFee      Decimal   @default(0.00) @db.Decimal(10, 2)\n  serviceFee       Decimal   @default(50.00) @db.Decimal(10, 2)\n  sourceUrl        String?\n  officialPdfUrl   String?\n  bannerUrl        String?\n  positions        Json // Array of sub-positions with salary grade, vacancy, requirements\n  eligibility      Json? // District catchment, age limit rules\n  instructions     Json? // Teletalk / Online application steps\n  status           JobStatus @default(PUBLISHED)\n  isFeatured       Boolean   @default(false)\n  viewsCount       Int       @default(0)\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  applications  ApplicationRequest[]\n  savedBy       SavedJob[]\n  examNotices   ExamNotice[]\n  admitCards    AdmitCard[]\n  examResults   ExamResult[]\n  userReminders UserJobReminder[]\n\n  @@map(\"job_circulars\")\n}\n\nmodel Category {\n  id          String        @id\n  slug        String        @unique\n  titleBn     String\n  titleEn     String\n  icon        String?\n  description String?\n  parentSlug  String?\n  isActive    Boolean       @default(true)\n  orderIndex  Int           @default(0)\n  jobs        JobCircular[]\n\n  @@map(\"categories\")\n}\n\nmodel Organization {\n  id          String   @id @default(uuid())\n  name        String\n  nameBn      String?\n  slug        String   @unique\n  logoUrl     String?\n  websiteUrl  String?\n  description String?\n  type        String? // Govt, Autonomous, Bank, Private\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"organizations\")\n}\n\nmodel JobSource {\n  id           String    @id\n  name         String\n  targetUrl    String\n  type         String?   @default(\"rss\")\n  frequency    String    @default(\"hourly\")\n  isEnabled    Boolean   @default(true)\n  trustScore   Int       @default(90)\n  lastRunAt    DateTime?\n  healthStatus String    @default(\"healthy\")\n  lastError    String?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@map(\"job_sources\")\n}\n\nmodel CircularDraft {\n  id            String   @id @default(uuid())\n  title         String\n  rawSourceData Json\n  status        String   @default(\"draft\")\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@map(\"circular_drafts\")\n}\n\n// -----------------------------------------------------\n// Module: wallet.prisma\n// -----------------------------------------------------\nmodel WalletTransaction {\n  id          String            @id\n  candidateId String\n  candidate   Candidate         @relation(fields: [candidateId], references: [id], onDelete: Cascade)\n  amount      Decimal           @db.Decimal(12, 2)\n  type        TransactionType\n  method      String            @default(\"wallet\")\n  trxId       String?\n  status      TransactionStatus @default(COMPLETED)\n  description String?\n  referenceId String?\n  createdAt   DateTime          @default(now())\n\n  @@map(\"wallet_transactions\")\n}\n\nmodel Coupon {\n  id            String       @id @default(uuid())\n  code          String       @unique\n  discountType  DiscountType @default(FIXED)\n  discountValue Decimal      @db.Decimal(10, 2)\n  maxDiscount   Decimal?     @db.Decimal(10, 2)\n  minSpend      Decimal?     @db.Decimal(10, 2)\n  usageLimit    Int?\n  usedCount     Int          @default(0)\n  status        CouponStatus @default(ACTIVE)\n  description   String?\n  stackable     Boolean      @default(true)\n  expiresAt     DateTime?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n\n  redemptions CouponRedemption[]\n\n  @@map(\"coupons\")\n}\n\nmodel CouponRedemption {\n  id              String    @id @default(uuid())\n  couponId        String\n  coupon          Coupon    @relation(fields: [couponId], references: [id], onDelete: Cascade)\n  candidateId     String\n  candidate       Candidate @relation(fields: [candidateId], references: [id], onDelete: Cascade)\n  discountApplied Decimal   @db.Decimal(10, 2)\n  createdAt       DateTime  @default(now())\n\n  @@map(\"coupon_redemptions\")\n}\n\nmodel RaffleCampaign {\n  id               String        @id @default(uuid())\n  title            String\n  description      String?\n  prizeDescription String?\n  rewardAmount     Decimal       @db.Decimal(10, 2)\n  status           String        @default(\"active\")\n  endsAt           DateTime?\n  winnerId         String?\n  createdAt        DateTime      @default(now())\n  entries          RaffleEntry[]\n\n  @@map(\"raffle_campaigns\")\n}\n\nmodel RaffleEntry {\n  id          String         @id @default(uuid())\n  campaignId  String\n  campaign    RaffleCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)\n  candidateId String\n  candidate   Candidate      @relation(fields: [candidateId], references: [id], onDelete: Cascade)\n  createdAt   DateTime       @default(now())\n\n  @@map(\"raffle_entries\")\n}\n"
}

